"""
Test cases for C++11 ref qualified member functions.
These tests should be added to the official test suite.
"""

import unittest
from test.testHelpers import get_cpp_function_list

class TestCppRefQualifiedFunctions(unittest.TestCase):

    def test_basic_ref_qualified_functions(self):
        """Test basic ref qualified member functions."""
        result = get_cpp_function_list("""
        struct A {
          void foo() & {}
          void bar() const & {}
          void baz() && {}
          void qux() const && {}
        };
        """)
        self.assertEqual(4, len(result))

        # Check function names and long names
        names_and_long_names = [(f.name, f.long_name) for f in result]
        expected = [
            ("A::foo", "A::foo() &"),
            ("A::bar", "A::bar() const &"), 
            ("A::baz", "A::baz() &&"),
            ("A::qux", "A::qux() const &&")
        ]

        for expected_name, expected_long_name in expected:
            found = any(name == expected_name and long_name == expected_long_name 
                       for name, long_name in names_and_long_names)
            self.assertTrue(found, f"Expected function {expected_name} with long name {expected_long_name}")

    def test_ref_qualified_with_noexcept(self):
        """Test ref qualified functions with noexcept."""
        result = get_cpp_function_list("""
        struct A {
          void foo() & noexcept {}
          void bar() const && noexcept(true) {}
        };
        """)
        self.assertEqual(2, len(result))

        # Find the functions and check their long names include both qualifiers
        long_names = [f.long_name for f in result]
        self.assertIn("A::foo() & noexcept", long_names)
        # Note: noexcept(true) might be parsed differently, so checking for the pattern
        bar_func = next(f for f in result if f.name == "A::bar")
        self.assertIn("const && noexcept", bar_func.long_name)

    def test_mixed_regular_and_ref_qualified(self):
        """Test mix of regular and ref qualified functions."""
        result = get_cpp_function_list("""
        class Test {
        public:
            void regular() {}
            void const_regular() const {}
            void lvalue_ref() & {}
            void rvalue_ref() && {}
            void const_lvalue_ref() const & {}
            void const_rvalue_ref() const && {}
        };
        """)
        self.assertEqual(6, len(result))

        long_names = [f.long_name for f in result]
        self.assertIn("Test::regular()", long_names)
        self.assertIn("Test::const_regular() const", long_names)
        self.assertIn("Test::lvalue_ref() &", long_names)
        self.assertIn("Test::rvalue_ref() &&", long_names)
        self.assertIn("Test::const_lvalue_ref() const &", long_names)
        self.assertIn("Test::const_rvalue_ref() const &&", long_names)

    def test_template_methods_with_ref_qualifiers(self):
        """Test template methods with ref qualifiers."""
        result = get_cpp_function_list("""
        class TemplateClass {
        public:
            template<typename T>
            void tmpl_method1() & {}

            template<typename T>
            void tmpl_method2() && {}
        };
        """)
        # Should detect the template methods
        self.assertGreaterEqual(len(result), 2)

        # At least check that ref qualified methods are detected
        ref_qualified_found = any("&" in f.long_name for f in result)
        self.assertTrue(ref_qualified_found, "Should find ref qualified template methods")

if __name__ == '__main__':
    unittest.main()"}

